package demo.pharma.catalog;
import demo.pharma.audit.AuditService; import demo.pharma.common.exception.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequiredArgsConstructor public class MasterDataController {private final CategoryRepository categories;private final ManufacturerRepository manufacturers;private final AuditService audit;
 record CategoryRequest(@NotBlank String name,String description,Boolean active){}record CategoryView(UUID id,String name,String description,boolean active){}record ManufacturerRequest(@NotBlank String name,String contactPerson,String phone,@Email String email,String address,String gstin,Boolean active){}record ManufacturerView(UUID id,String name,String contactPerson,String phone,String email,String address,String gstin,boolean active){}
 @GetMapping("/api/categories")@PreAuthorize("hasAuthority('MEDICINE_VIEW')")List<CategoryView> categories(){return categories.findAll().stream().map(this::cv).toList();}@GetMapping("/api/categories/{id}")@PreAuthorize("hasAuthority('MEDICINE_VIEW')")CategoryView category(@PathVariable UUID id){return cv(categoryEntity(id));}@PostMapping("/api/categories")@PreAuthorize("hasAuthority('MEDICINE_CREATE')")CategoryView categoryCreate(@Valid@RequestBody CategoryRequest r){if(categories.existsByNameIgnoreCase(r.name()))throw new BusinessException("Category name already exists");Category c=new Category();apply(c,r);categories.save(c);audit.logCurrent("CATEGORY_CREATED","CATEGORY",c.getId(),null,c.getName());return cv(c);}@PutMapping("/api/categories/{id}")@PreAuthorize("hasAuthority('MEDICINE_UPDATE')")CategoryView categoryUpdate(@PathVariable UUID id,@Valid@RequestBody CategoryRequest r){Category c=categoryEntity(id);apply(c,r);categories.save(c);audit.logCurrent("CATEGORY_UPDATED","CATEGORY",id,null,c.getName());return cv(c);}@DeleteMapping("/api/categories/{id}")@PreAuthorize("hasAuthority('MEDICINE_DELETE')")void categoryDelete(@PathVariable UUID id){Category c=categoryEntity(id);c.setActive(false);categories.save(c);audit.logCurrent("CATEGORY_DEACTIVATED","CATEGORY",id,null,null);}
 @GetMapping("/api/manufacturers")@PreAuthorize("hasAuthority('MEDICINE_VIEW')")List<ManufacturerView> manufacturers(){return manufacturers.findAll().stream().map(this::mv).toList();}@GetMapping("/api/manufacturers/{id}")@PreAuthorize("hasAuthority('MEDICINE_VIEW')")ManufacturerView manufacturer(@PathVariable UUID id){return mv(manufacturerEntity(id));}@PostMapping("/api/manufacturers")@PreAuthorize("hasAuthority('MEDICINE_CREATE')")ManufacturerView manufacturerCreate(@Valid@RequestBody ManufacturerRequest r){Manufacturer m=new Manufacturer();apply(m,r);manufacturers.save(m);audit.logCurrent("MANUFACTURER_CREATED","MANUFACTURER",m.getId(),null,m.getName());return mv(m);}@PutMapping("/api/manufacturers/{id}")@PreAuthorize("hasAuthority('MEDICINE_UPDATE')")ManufacturerView manufacturerUpdate(@PathVariable UUID id,@Valid@RequestBody ManufacturerRequest r){Manufacturer m=manufacturerEntity(id);apply(m,r);manufacturers.save(m);audit.logCurrent("MANUFACTURER_UPDATED","MANUFACTURER",id,null,m.getName());return mv(m);}@DeleteMapping("/api/manufacturers/{id}")@PreAuthorize("hasAuthority('MEDICINE_DELETE')")void manufacturerDelete(@PathVariable UUID id){Manufacturer m=manufacturerEntity(id);m.setActive(false);manufacturers.save(m);audit.logCurrent("MANUFACTURER_DEACTIVATED","MANUFACTURER",id,null,null);}
 private Category categoryEntity(UUID id){return categories.findById(id).orElseThrow(()->new NotFoundException("Category",id));}private Manufacturer manufacturerEntity(UUID id){return manufacturers.findById(id).orElseThrow(()->new NotFoundException("Manufacturer",id));}private void apply(Category c,CategoryRequest r){c.setName(r.name().trim());c.setDescription(r.description());if(r.active()!=null)c.setActive(r.active());}private void apply(Manufacturer m,ManufacturerRequest r){m.setName(r.name().trim());m.setContactPerson(r.contactPerson());m.setPhone(r.phone());m.setEmail(r.email());m.setAddress(r.address());m.setGstin(r.gstin());if(r.active()!=null)m.setActive(r.active());}private CategoryView cv(Category c){return new CategoryView(c.getId(),c.getName(),c.getDescription(),c.isActive());}private ManufacturerView mv(Manufacturer m){return new ManufacturerView(m.getId(),m.getName(),m.getContactPerson(),m.getPhone(),m.getEmail(),m.getAddress(),m.getGstin(),m.isActive());}}
